```c
for(i = 0; i < rar5_countof(rar->cstate.dready); i++) {
    struct data_ready* d = &rar->cstate.dready[i];
    if(!d->used) {
        d->used = 1;
        d->buf = buf;
        ...
    }
}
```

And `use_data`:
```c
for(i = 0; i < rar5_countof(rar->cstate.dready); i++) {
    struct data_ready *d = &rar->cstate.dready[i];
    if(d->used) {
        if(buf)    *buf = d->buf;
        ...
        d->used = 0;
        return ARCHIVE_OK;
    }
}
return ARCHIVE_RETRY;
```

So when `use_data` returns `ARCHIVE_RETRY`, all `d->used` are 0. Then `do_unpack` is called, which calls `init_unpack`, which frees `window_buf`. This is safe because no `d->buf` points into `window_buf` anymore.

